"""Synthetic register workbooks, generated by the tests that use them.

No real workbook ever enters CI, and no ``.xlsx`` is committed at all — the
repository ignores the extension outright, so a checked-in workbook could only
be a real one that arrived by accident. These builders produce a file with the
same *shape* as the real register and none of its content.

Every name and title here is invented. The eras, the column moves, the
pre-numbering and the anomalies are real, because those are what the parser has
to survive; the matters are not.
"""

from __future__ import annotations

import datetime as dt
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from openpyxl import Workbook
from openpyxl.worksheet.hyperlink import Hyperlink

from app.workflow.vocabulary import RAW_LABEL_TO_DISPOSITION, RAW_LABEL_TO_STAGE

#: Column layouts, matching the reviewed era contracts exactly. Kept here rather
#: than derived from the contracts so that a contract edited by mistake shows up
#: as a test failure instead of being silently agreed with.
HEADERS_2011 = [
    "NR",
    "TEEMA",
    "ÕIGUSAKT",
    "SISSE",
    "ARVAMUSE TÄHTAEG",
    "VÄLJA",
    "KELLELT",
    "VASTUTAJA",
]
FEEDBACK_HEADERS = [
    "LIIKMETE ARV, KES ANDSID TAGASISIDET",
    "LIIKMETE ARV, KELLELT OTSE KÜSISIME TAGASISIDET",
]
HEADERS_2018 = [*HEADERS_2011, *FEEDBACK_HEADERS]
HEADERS_2020 = [
    "NR",
    "TEEMA",
    "ÕIGUSAKT",
    "SISSE",
    "ARVAMUSE TÄHTAEG",
    "VÄLJA",
    "KELLELE",
    "VASTUTAJA",
    *FEEDBACK_HEADERS,
]
HEADERS_2023 = [*HEADERS_2020, "HETKESEIS"]
HEADERS_2025 = [*HEADERS_2023, "JÄRGMISEKS"]

HEADERS_BY_YEAR: dict[int, list[str]] = {
    **dict.fromkeys(range(2011, 2018), HEADERS_2011),
    2018: HEADERS_2018,
    2019: HEADERS_2018,
    2020: HEADERS_2020,
    2021: HEADERS_2020,
    2022: HEADERS_2020,
    2023: HEADERS_2023,
    2024: HEADERS_2023,
    2025: HEADERS_2025,
    2026: HEADERS_2025,
}

ONENOTE_LINK = "onenote:https://example.invalid/Notebook/Section#Page&section-id=synthetic"


@dataclass
class Row:
    """One synthetic register row. ``None`` is a blank cell, and it stays blank."""

    reference: str | None = None
    title: str | None = None
    instrument: str | None = None
    received: Any = None
    deadline: Any = None
    sent: Any = None
    counterparty: str | None = None
    owner: str | None = None
    responded: Any = None
    requested: Any = None
    status: str | None = None
    next_action: str | None = None
    extra: Any = None
    hyperlink: str | None = None

    def cells(self, year: int) -> list[Any]:
        values: list[Any] = [
            self.reference,
            self.title,
            self.instrument,
            self.received,
            self.deadline,
            self.sent,
            self.counterparty,
            self.owner,
        ]
        if year >= 2018:
            values += [self.responded, self.requested]
        if year == 2022:
            values.append(self.extra)
        if year >= 2023:
            values.append(self.status)
        if year >= 2025:
            values.append(self.next_action)
        return values


@dataclass
class Sheet:
    year: int
    rows: list[Row] = field(default_factory=list)


def _headers_for(year: int) -> list[str]:
    headers = list(HEADERS_BY_YEAR[year])
    if year == 2022:
        # The unlabelled column the real 2022 sheet carries. Its position
        # matters; its meaning is not established and must stay that way.
        headers = [*HEADERS_2020, ""]
    return headers


def write_workbook(path: Path, sheets: list[Sheet], *, vocabulary: bool = True) -> Path:
    """Write a workbook laid out like the register. Returns the path."""
    workbook = Workbook()
    workbook.remove(workbook.active)

    for sheet in sorted(sheets, key=lambda s: -s.year):
        worksheet = workbook.create_sheet(title=str(sheet.year))
        header_row = 1
        if sheet.year == 2021:
            # The 2021 sheet really does put a title above its headers.
            worksheet.append([f"Tööd eelnõudega {sheet.year}"])
            header_row = 2
        worksheet.append(_headers_for(sheet.year))

        for offset, row in enumerate(sheet.rows):
            worksheet.append(row.cells(sheet.year))
            if row.hyperlink:
                cell = worksheet.cell(row=header_row + 1 + offset, column=2)
                cell.hyperlink = Hyperlink(ref=cell.coordinate, target=row.hyperlink)

    if vocabulary:
        reference = workbook.create_sheet(title="Hetkeseisu info")
        reference.append(["HETKESEISU ETAPP", "SELGITUS"])
        for label in [*RAW_LABEL_TO_STAGE, *RAW_LABEL_TO_DISPOSITION]:
            reference.append([label, f"Sünteetiline selgitus: {label}."])

    path.parent.mkdir(parents=True, exist_ok=True)
    workbook.save(path)
    workbook.close()
    return path


