def duplicate_reference_corpus() -> list[Sheet]:
    return [
        Sheet(
            2026,
            [
                Row(reference="2026_1", title="Sünteetiline esimene", owner="Kadri"),
                Row(reference="2026_1", title="Sünteetiline teine", owner="Kadri"),
                Row(reference="mitte viide", title="Sünteetiline vigase viitega", owner="Kadri"),
            ],
        )
    ]


def pre_numbered_corpus(*, filled: int = 2, reserved_to: int = 300) -> list[Sheet]:
    """A 2026 sheet numbered to ``reserved_to`` with only ``filled`` rows used."""
    rows = [
        Row(
            reference=f"2026_{number}",
            title=f"Sünteetiline teema {number}",
            received=dt.datetime(2026, 1, number % 28 + 1),
            counterparty="Näidisministeerium",
            owner="Kadri",
            status="kooskõlastusringil",
        )
        for number in range(1, filled + 1)
    ]
    rows += [Row(reference=f"2026_{number}") for number in range(filled + 1, reserved_to + 1)]
    return [Sheet(2026, rows)]
